---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"input">

const {
  class: className,
  "data-slot": dataSlot = "input",
  multiple,
  ...props
} = Astro.props

// Astro renders `multiple` as `multiple="true"` or `multiple="false"`, and both
// enable it. Render the bare attribute only when it is set.
---

<input
  data-slot={dataSlot}
  multiple={multiple ? "" : undefined}
  class={cn(
    "border-transparent border-b-input bg-transparent focus-visible:border-b-ring aria-invalid:border-b-destructive dark:aria-invalid:border-b-destructive/50 h-10 border px-0 py-1 text-base transition-[color,border-color] file:h-7 file:text-sm file:font-medium md:text-sm file:text-foreground placeholder:text-muted-foreground w-full min-w-0 outline-none file:inline-flex file:border-0 file:bg-transparent disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50",
    className
  )}
  {...props}
/>
